from collections import Counter

def maxScoreWords(words, letters, score):
    def score_word(word, score_map):
        return sum(score_map[char] for char in word)

    def can_form(word, letter_count):
        word_count = Counter(word)
        for char, count in word_count.items():
            if letter_count[char] < count:
                return False
        return True

    def update_letter_count(letter_count, word, add=True):
        for char in word:
            letter_count[char] += 1 if add else -1

    def backtrack(index, current_score, letter_count):
        if index == len(words):
            return current_score
        max_score = current_score
        if can_form(words[index], letter_count):
            update_letter_count(letter_count, words[index], add=False)
            max_score = max(max_score, backtrack(index + 1, current_score + score_word(words[index], score_map), letter_count))
            update_letter_count(letter_count, words[index], add=True)
        max_score = max(max_score, backtrack(index + 1, current_score, letter_count))
        return max_score

    score_map = {chr(i + ord('a')): score[i] for i in range(26)}
    letter_count = Counter(letters)
    return backtrack(0, 0, letter_count)
